  1	package br.marealta;
  2	
  3	import br.marealta.api.MessageController;
  4	import br.marealta.api.ReportController;
  5	import br.marealta.api.ReservationController;
  6	import br.marealta.api.RoomController;
  7	import br.marealta.db.*;
  8	import br.marealta.service.*;
  9	import io.javalin.Javalin;
 10	import org.slf4j.Logger;
 11	import org.slf4j.LoggerFactory;
 12	
 13	public class Main {
 14	    private static final Logger logger = LoggerFactory.getLogger(Main.class);
 15	
 16	    public static void main(String[] args) {
 17	        Database db = Database.getInstance();
 18	
 19	        RoomDAO roomDAO = new RoomDAO(db);
 20	        ReservationDAO reservationDAO = new ReservationDAO(db);
 21	        MessageDAO messageDAO = new MessageDAO(db);
 22	
 23	        RoomService roomService = new RoomService(roomDAO);
 24	        NotificationService notificationService = new NotificationService(messageDAO);
 25	        ReservationService reservationService = new ReservationService(reservationDAO, roomDAO, notificationService);
 26	        ReportService reportService = new ReportService(reservationDAO, roomDAO);
 27	
 28	        notificationService.registerHandler(new DefaultNotificationHandler(notificationService));
 29	
 30	        RoomController roomController = new RoomController(roomService);
 31	        ReservationController reservationController = new ReservationController(reservationService);
 32	        MessageController messageController = new MessageController(messageDAO);
 33	        ReportController reportController = new ReportController(reportService);
 34	
 35	        String port = System.getenv("PORT");
 36	        if (port == null) {
 37	            port = "7070";
 38	        }
 39	
 40	        Javalin app = Javalin.create()
 41	            .get("/rooms", roomController::getRooms)
 42	            .post("/reservations", reservationController::createReservation)
 43	            .get("/reservations/{id}", reservationController::getReservation)
 44	            .post("/reservations/{id}/confirmation", reservationController::confirmReservation)
 45	            .post("/reservations/{id}/cancellation", reservationController::cancelReservation)
 46	            .post("/reservations/{id}/check-in", reservationController::checkIn)
 47	            .post("/reservations/{id}/check-out", reservationController::checkOut)
 48	            .get("/reservations/{id}/document", reservationController::getDocument)
 49	            .get("/messages", messageController::getMessages)
 50	            .get("/reports/occupancy", reportController::getOccupancyReport)
 51	            .get("/reports/revenue", reportController::getRevenueReport)
 52	            .start(Integer.parseInt(port));
 53	
 54	        logger.info("Server started on port {}", port);
 55	    }
 56	}
 57	package br.marealta.api;
