 81	package br.marealta.api;
 82	
 83	import br.marealta.service.ReportService;
 84	import br.marealta.util.Formatters;
 85	import io.javalin.http.Context;
 86	
 87	import java.time.LocalDate;
 88	import java.util.Map;
 89	
 90	public class ReportController {
 91	    private final ReportService reportService;
 92	
 93	    public ReportController(ReportService reportService) {
 94	        this.reportService = reportService;
 95	    }
 96	
 97	    public void getOccupancyReport(Context ctx) {
 98	        try {
 99	            String dateStr = ctx.queryParam("date");
100	            if (dateStr == null || dateStr.isEmpty()) {
101	                ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Date parameter required"));
102	                return;
103	            }
104	
105	            LocalDate date = Formatters.parseIsoDate(dateStr);
106	            String report = reportService.generateOccupancyReport(date);
107	
108	            ctx.header("Content-Type", "text/csv; charset=utf-8");
109	            ctx.result(report);
110	        } catch (Exception e) {
111	            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Invalid date format"));
112	        }
113	    }
114	
115	    public void getRevenueReport(Context ctx) {
116	        try {
117	            String monthStr = ctx.queryParam("month");
118	            if (monthStr == null || monthStr.isEmpty()) {
119	                ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Month parameter required"));
120	                return;
121	            }
122	
123	            String[] parts = monthStr.split("-");
124	            if (parts.length != 2) {
125	                ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Invalid month format"));
126	                return;
127	            }
128	
129	            int year = Integer.parseInt(parts[0]);
130	            int month = Integer.parseInt(parts[1]);
131	
132	            if (month < 1 || month > 12) {
133	                ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Invalid month"));
134	                return;
135	            }
136	
137	            String report = reportService.generateRevenueReport(year, month);
138	
139	            ctx.header("Content-Type", "text/csv; charset=utf-8");
140	            ctx.result(report);
141	        } catch (NumberFormatException e) {
142	            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Invalid month format"));
143	        }
144	    }
145	}
146	package br.marealta.api;
147	
148	import br.marealta.model.RatePlan;
149	import br.marealta.model.Reservation;
150	import br.marealta.service.ReservationService;
151	import br.marealta.util.Formatters;
152	import io.javalin.http.Context;
153	
154	import java.math.BigDecimal;
155	import java.time.LocalDate;
156	import java.util.HashMap;
157	import java.util.Map;
158	
159	public class ReservationController {
160	    private final ReservationService reservationService;
161	
162	    public ReservationController(ReservationService reservationService) {
163	        this.reservationService = reservationService;
164	    }
165	
166	    public void createReservation(Context ctx) {
167	        try {
168	            Map<String, Object> body = ctx.bodyAsClass(Map.class);
169	
170	            int roomNumber = ((Number) body.get("roomNumber")).intValue();
171	            String guestName = (String) body.get("guestName");
172	            String guestEmail = (String) body.get("guestEmail");
173	            String guestCpf = (String) body.get("guestCpf");
174	            String checkInStr = (String) body.get("checkIn");
175	            String checkOutStr = (String) body.get("checkOut");
176	            int guests = ((Number) body.get("guests")).intValue();
177	            String ratePlanStr = (String) body.get("ratePlan");
178	
179	            validateCreateReservationInput(roomNumber, guestName, guestEmail, guestCpf,
180	                checkInStr, checkOutStr, guests, ratePlanStr);
181	
182	            LocalDate checkIn = Formatters.parseIsoDate(checkInStr);
183	            LocalDate checkOut = Formatters.parseIsoDate(checkOutStr);
184	            RatePlan ratePlan = RatePlan.valueOf(ratePlanStr);
185	
186	            Reservation reservation = reservationService.createReservation(
187	                roomNumber, guestName, guestEmail, guestCpf,
188	                checkIn, checkOut, guests, ratePlan);
189	
190	            ctx.status(201).json(toResponse(reservation));
191	        } catch (IllegalArgumentException e) {
192	            handleError(ctx, e.getMessage());
193	        } catch (Exception e) {
194	            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Invalid request body"));
195	        }
196	    }
197	
198	    public void getReservation(Context ctx) {
199	        try {
200	            long id = ctx.pathParamAsClass("id", Long.class).get();
201	            Reservation reservation = reservationService.getReservation(id);
202	            ctx.json(toResponse(reservation));
203	        } catch (IllegalArgumentException e) {
204	            handleError(ctx, e.getMessage());
205	        }
206	    }
207	
208	    public void confirmReservation(Context ctx) {
209	        try {
210	            long id = ctx.pathParamAsClass("id", Long.class).get();
211	            Map<String, Object> body = ctx.bodyAsClass(Map.class);
212	
213	            if (!body.containsKey("amountPaid")) {
214	                ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Missing amountPaid"));
215	                return;
216	            }
217	
218	            BigDecimal amountPaid = new BigDecimal(body.get("amountPaid").toString());
219	
220	            Reservation reservation = reservationService.confirmReservation(id, amountPaid);
221	            ctx.json(toResponse(reservation));
222	        } catch (IllegalArgumentException e) {
223	            handleError(ctx, e.getMessage());
224	        } catch (Exception e) {
225	            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Invalid request body"));
226	        }
227	    }
228	
229	    public void cancelReservation(Context ctx) {
230	        try {
231	            long id = ctx.pathParamAsClass("id", Long.class).get();
232	            Reservation reservation = reservationService.cancelReservation(id);
233	            ctx.json(toResponse(reservation));
234	        } catch (IllegalArgumentException e) {
235	            handleError(ctx, e.getMessage());
236	        }
237	    }
238	
239	    public void checkIn(Context ctx) {
240	        try {
241	            long id = ctx.pathParamAsClass("id", Long.class).get();
242	            Reservation reservation = reservationService.checkIn(id);
243	            ctx.json(toResponse(reservation));
244	        } catch (IllegalArgumentException e) {
245	            handleError(ctx, e.getMessage());
246	        }
247	    }
248	
249	    public void checkOut(Context ctx) {
250	        try {
251	            long id = ctx.pathParamAsClass("id", Long.class).get();
252	            Reservation reservation = reservationService.checkOut(id);
253	            String document = reservationService.generateConfirmation(reservation);
254	            Map<String, Object> response = new HashMap<>();
255	            response.put("title", "Comprovante de reserva");
256	            response.put("reservationId", reservation.getId());
257	            response.put("guestName", reservation.getGuestName());
258	            response.put("guestCpf", reservation.getGuestCpf());
259	            response.put("roomNumber", reservation.getRoomNumber());
260	            response.put("roomType", reservation.getRoomNumber());
261	            response.put("checkIn", Formatters.formatDate(reservation.getCheckIn()));
262	            response.put("checkOut", Formatters.formatDate(reservation.getCheckOut()));
263	            response.put("nights", reservation.getNights());
264	            response.put("subtotal", reservation.getSubtotal().doubleValue());
265	            response.put("discount", reservation.getDiscount().doubleValue());
266	            response.put("total", reservation.getTotal().doubleValue());
267	            ctx.json(response);
268	        } catch (IllegalArgumentException e) {
269	            handleError(ctx, e.getMessage());
270	        }
271	    }
272	
273	    public void getDocument(Context ctx) {
274	        try {
275	            long id = ctx.pathParamAsClass("id", Long.class).get();
276	            Reservation reservation = reservationService.getReservation(id);
277	
278	            if (reservation.getAmountPaid().compareTo(java.math.BigDecimal.ZERO) == 0) {
279	                ctx.status(409).json(Map.of("error", "OPERATION_NOT_ALLOWED",
280	                    "message", "Document only available for paid reservations"));
281	                return;
282	            }
283	
284	            String document = reservationService.generateConfirmation(reservation);
285	            Map<String, Object> response = new HashMap<>();
286	            response.put("title", "Comprovante de reserva");
287	            response.put("reservationId", reservation.getId());
288	            response.put("guestName", reservation.getGuestName());
289	            response.put("guestCpf", reservation.getGuestCpf());
290	            response.put("roomNumber", reservation.getRoomNumber());
291	            response.put("roomType", reservation.getRoomNumber());
292	            response.put("checkIn", Formatters.formatDate(reservation.getCheckIn()));
293	            response.put("checkOut", Formatters.formatDate(reservation.getCheckOut()));
294	            response.put("nights", reservation.getNights());
295	            response.put("subtotal", reservation.getSubtotal().doubleValue());
296	            response.put("discount", reservation.getDiscount().doubleValue());
297	            response.put("total", reservation.getTotal().doubleValue());
298	            ctx.json(response);
299	        } catch (IllegalArgumentException e) {
300	            handleError(ctx, e.getMessage());
301	        }
302	    }
303	
304	    private Map<String, Object> toResponse(Reservation reservation) {
305	        Map<String, Object> map = new HashMap<>();
306	        map.put("id", reservation.getId());
307	        map.put("roomNumber", reservation.getRoomNumber());
308	        map.put("guestName", reservation.getGuestName());
309	        map.put("guestEmail", reservation.getGuestEmail());
310	        map.put("guestCpf", reservation.getGuestCpf());
311	        map.put("checkIn", Formatters.formatDate(reservation.getCheckIn()));
312	        map.put("checkOut", Formatters.formatDate(reservation.getCheckOut()));
313	        map.put("guests", reservation.getGuests());
314	        map.put("ratePlan", reservation.getRatePlan().name());
315	        map.put("nights", reservation.getNights());
316	        map.put("subtotal", reservation.getSubtotal().doubleValue());
317	        map.put("discount", reservation.getDiscount().doubleValue());
318	        map.put("total", reservation.getTotal().doubleValue());
319	        map.put("status", reservation.getStatus().name());
320	        map.put("amountPaid", reservation.getAmountPaid().doubleValue());
321	        map.put("refund", reservation.getRefund());
322	        return map;
323	    }
324	
325	    private void validateCreateReservationInput(int roomNumber, String guestName, String guestEmail,
326	                                               String guestCpf, String checkIn, String checkOut,
327	                                               int guests, String ratePlan) {
328	        if (roomNumber <= 0 || guestName == null || guestName.isEmpty() ||
329	            guestEmail == null || guestEmail.isEmpty() || guestCpf == null || guestCpf.isEmpty() ||
330	            checkIn == null || checkOut == null || guests <= 0 || ratePlan == null) {
331	            throw new IllegalArgumentException("INVALID_REQUEST");
332	        }
333	
334	        try {
335	            Formatters.parseIsoDate(checkIn);
336	            Formatters.parseIsoDate(checkOut);
337	            RatePlan.valueOf(ratePlan);
338	        } catch (Exception e) {
339	            throw new IllegalArgumentException("INVALID_REQUEST");
340	        }
341	    }
342	
343	    private void handleError(Context ctx, String errorCode) {
344	        switch (errorCode) {
345	            case "ROOM_NOT_FOUND":
346	                ctx.status(404).json(Map.of("error", "ROOM_NOT_FOUND", "message", "Room not found"));
347	                break;
348	            case "RESERVATION_NOT_FOUND":
349	                ctx.status(404).json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Reservation not found"));
350	                break;
351	            case "ROOM_UNAVAILABLE":
352	                ctx.status(409).json(Map.of("error", "ROOM_UNAVAILABLE", "message", "Room is unavailable for selected dates"));
353	                break;
354	            case "CAPACITY_EXCEEDED":
355	                ctx.status(422).json(Map.of("error", "CAPACITY_EXCEEDED", "message", "Number of guests exceeds room capacity"));
356	                break;
357	            case "OPERATION_NOT_ALLOWED":
358	                ctx.status(409).json(Map.of("error", "OPERATION_NOT_ALLOWED", "message", "Operation not allowed for this reservation status"));
359	                break;
360	            case "INVALID_REQUEST":
361	            default:
362	                ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Invalid request"));
363	                break;
364	        }
365	    }
366	}
