275	            long id = ctx.pathParamAsClass("id", Long.class).get();
276	            Reservation reservation = reservationService.getReservation(id);
277	
278	            if (reservation.getAmountPaid().compareTo(java.math.BigDecimal.ZERO) == 0) {
279	                ctx.status(409).json(Map.of("error", "OPERATION_NOT_ALLOWED",
280	                    "message", "Document only available for paid reservations"));
281	                return;
282	            }
283	
284	            String document = reservationService.generateConfirmation(reservation);
285	            Map<String, Object> response = new HashMap<>();
286	            response.put("title", "Comprovante de reserva");
287	            response.put("reservationId", reservation.getId());
288	            response.put("guestName", reservation.getGuestName());
289	            response.put("guestCpf", reservation.getGuestCpf());
290	            response.put("roomNumber", reservation.getRoomNumber());
291	            response.put("roomType", reservation.getRoomNumber());
292	            response.put("checkIn", Formatters.formatDate(reservation.getCheckIn()));
293	            response.put("checkOut", Formatters.formatDate(reservation.getCheckOut()));
294	            response.put("nights", reservation.getNights());
295	            response.put("subtotal", reservation.getSubtotal().doubleValue());
296	            response.put("discount", reservation.getDiscount().doubleValue());
297	            response.put("total", reservation.getTotal().doubleValue());
298	            ctx.json(response);
299	        } catch (IllegalArgumentException e) {
300	            handleError(ctx, e.getMessage());
301	        }
302	    }
303	
304	    private Map<String, Object> toResponse(Reservation reservation) {
305	        Map<String, Object> map = new HashMap<>();
306	        map.put("id", reservation.getId());
307	        map.put("roomNumber", reservation.getRoomNumber());
308	        map.put("guestName", reservation.getGuestName());
309	        map.put("guestEmail", reservation.getGuestEmail());
310	        map.put("guestCpf", reservation.getGuestCpf());
311	        map.put("checkIn", Formatters.formatDate(reservation.getCheckIn()));
312	        map.put("checkOut", Formatters.formatDate(reservation.getCheckOut()));
313	        map.put("guests", reservation.getGuests());
314	        map.put("ratePlan", reservation.getRatePlan().name());
315	        map.put("nights", reservation.getNights());
316	        map.put("subtotal", reservation.getSubtotal().doubleValue());
317	        map.put("discount", reservation.getDiscount().doubleValue());
318	        map.put("total", reservation.getTotal().doubleValue());
319	        map.put("status", reservation.getStatus().name());
320	        map.put("amountPaid", reservation.getAmountPaid().doubleValue());
321	        map.put("refund", reservation.getRefund());
322	        return map;
323	    }
324	
325	    private void validateCreateReservationInput(int roomNumber, String guestName, String guestEmail,
326	                                               String guestCpf, String checkIn, String checkOut,
327	                                               int guests, String ratePlan) {
328	        if (roomNumber <= 0 || guestName == null || guestName.isEmpty() ||
329	            guestEmail == null || guestEmail.isEmpty() || guestCpf == null || guestCpf.isEmpty() ||
330	            checkIn == null || checkOut == null || guests <= 0 || ratePlan == null) {
331	            throw new IllegalArgumentException("INVALID_REQUEST");
332	        }
333	
334	        try {
335	            Formatters.parseIsoDate(checkIn);
336	            Formatters.parseIsoDate(checkOut);
337	            RatePlan.valueOf(ratePlan);
338	        } catch (Exception e) {
339	            throw new IllegalArgumentException("INVALID_REQUEST");
340	        }
341	    }
342	
343	    private void handleError(Context ctx, String errorCode) {
344	        switch (errorCode) {
345	            case "ROOM_NOT_FOUND":
346	                ctx.status(404).json(Map.of("error", "ROOM_NOT_FOUND", "message", "Room not found"));
347	                break;
348	            case "RESERVATION_NOT_FOUND":
349	                ctx.status(404).json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Reservation not found"));
350	                break;
351	            case "ROOM_UNAVAILABLE":
352	                ctx.status(409).json(Map.of("error", "ROOM_UNAVAILABLE", "message", "Room is unavailable for selected dates"));
353	                break;
354	            case "CAPACITY_EXCEEDED":
355	                ctx.status(422).json(Map.of("error", "CAPACITY_EXCEEDED", "message", "Number of guests exceeds room capacity"));
356	                break;
357	            case "OPERATION_NOT_ALLOWED":
358	                ctx.status(409).json(Map.of("error", "OPERATION_NOT_ALLOWED", "message", "Operation not allowed for this reservation status"));
359	                break;
360	            case "INVALID_REQUEST":
361	            default:
362	                ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Invalid request"));
363	                break;
364	        }
365	    }
366	}
