141	public class NotificationService {
142	    private static final Logger logger = LoggerFactory.getLogger(NotificationService.class);
143	    private final MessageDAO messageDAO;
144	    private final List<NotificationHandler> handlers = new ArrayList<>();
145	
146	    public NotificationService(MessageDAO messageDAO) {
147	        this.messageDAO = messageDAO;
148	    }
149	
150	    public void registerHandler(NotificationHandler handler) {
151	        handlers.add(handler);
152	    }
153	
154	    public void send(Notification notification) {
155	        Message message = new Message(
156	            notification.getChannel(),
157	            notification.getTo(),
158	            notification.getSubject(),
159	            notification.getBody()
160	        );
161	        messageDAO.save(message);
162	        logger.info("Notification sent to {} with subject '{}'", notification.getTo(), notification.getSubject());
163	    }
164	
165	    public void notifyReservationConfirmed(Reservation reservation) {
166	        for (NotificationHandler handler : handlers) {
167	            try {
168	                handler.onReservationConfirmed(reservation);
169	            } catch (Exception e) {
170	                logger.error("Error notifying handler on reservation confirmed", e);
171	            }
172	        }
173	    }
174	
175	    public void notifyReservationCancelled(Reservation reservation) {
176	        for (NotificationHandler handler : handlers) {
177	            try {
178	                handler.onReservationCancelled(reservation);
179	            } catch (Exception e) {
180	                logger.error("Error notifying handler on reservation cancelled", e);
181	            }
182	        }
183	    }
184	}
