196	
197	public class ReportService {
198	    private final ReservationDAO reservationDAO;
199	    private final RoomDAO roomDAO;
200	
201	    public ReportService(ReservationDAO reservationDAO, RoomDAO roomDAO) {
202	        this.reservationDAO = reservationDAO;
203	        this.roomDAO = roomDAO;
204	    }
205	
206	    public String generateOccupancyReport(LocalDate date) {
207	        List<Reservation> reservations = reservationDAO.findByDate(date);
208	        List<Room> allRooms = roomDAO.findAll();
209	
210	        StringBuilder csv = new StringBuilder();
211	        csv.append("room,type,reservation,check_in,check_out\n");
212	
213	        for (Room room : allRooms) {
214	            Reservation res = reservations.stream()
215	                .filter(r -> r.getRoomNumber() == room.getNumber())
216	                .findFirst()
217	                .orElse(null);
218	
219	            if (res != null) {
220	                csv.append(String.format("%d,%s,%d,%s,%s\n",
221	                    room.getNumber(),
222	                    room.getType().name(),
223	                    res.getId(),
224	                    Formatters.formatDateForCsv(res.getCheckIn()),
225	                    Formatters.formatDateForCsv(res.getCheckOut())));
226	            }
227	        }
228	
229	        int occupiedRooms = (int) reservations.stream().map(Reservation::getRoomNumber).distinct().count();
230	        csv.append(String.format("total,%d/%d\n", occupiedRooms, allRooms.size()));
231	
232	        return csv.toString();
233	    }
234	
235	    public String generateRevenueReport(int year, int month) {
236	        List<Reservation> reservations = reservationDAO.findByMonth(year, month);
237	
238	        StringBuilder csv = new StringBuilder();
239	        csv.append("reservation,room,check_in,check_out,status,amount\n");
240	
241	        BigDecimal total = BigDecimal.ZERO;
242	
243	        for (Reservation res : reservations) {
244	            BigDecimal amount = res.getAmountPaid();
245	
246	            if (res.getRefund() != null) {
247	                amount = amount.subtract(res.getRefund());
248	            }
249	
250	            csv.append(String.format("%d,%d,%s,%s,%s,%s\n",
251	                res.getId(),
252	                res.getRoomNumber(),
253	                Formatters.formatDateForCsv(res.getCheckIn()),
254	                Formatters.formatDateForCsv(res.getCheckOut()),
255	                res.getStatus().name(),
256	                Formatters.formatMoneyForCsv(amount)));
257	
258	            total = total.add(amount);
259	        }
260	
261	        csv.append(String.format("total,%s", Formatters.formatMoneyForCsv(total)));
262	
263	        return csv.toString();
264	    }
265	}
266	package br.marealta.service;
267	
268	import br.marealta.db.MessageDAO;
269	import br.marealta.db.ReservationDAO;
270	import br.marealta.db.RoomDAO;
271	import br.marealta.model.*;
272	import br.marealta.util.Formatters;
273	import br.marealta.util.PricingCalculator;
274	import org.slf4j.Logger;
275	import org.slf4j.LoggerFactory;
276	
277	import java.math.BigDecimal;
278	import java.time.LocalDate;
279	
280	public class ReservationService {
281	    private static final Logger logger = LoggerFactory.getLogger(ReservationService.class);
282	    private final ReservationDAO reservationDAO;
283	    private final RoomDAO roomDAO;
284	    private final NotificationService notificationService;
285	
286	    public ReservationService(ReservationDAO reservationDAO, RoomDAO roomDAO,
287	                              NotificationService notificationService) {
288	        this.reservationDAO = reservationDAO;
289	        this.roomDAO = roomDAO;
290	        this.notificationService = notificationService;
291	    }
292	
293	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail,
294	                                         String guestCpf, LocalDate checkIn, LocalDate checkOut,
295	                                         int guests, RatePlan ratePlan) {
296	        validateInput(roomNumber, checkIn, checkOut, guests);
297	
298	        Room room = roomDAO.findByNumber(roomNumber)
299	            .orElseThrow(() -> new IllegalArgumentException("ROOM_NOT_FOUND"));
300	
301	        if (guests > room.getCapacity()) {
302	            throw new IllegalArgumentException("CAPACITY_EXCEEDED");
303	        }
304	
305	        if (isRoomUnavailable(roomNumber, checkIn, checkOut)) {
306	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
307	        }
308	
309	        Reservation reservation = new Reservation(roomNumber, guestName, guestEmail, guestCpf,
310	            checkIn, checkOut, guests, ratePlan);
311	
312	        int nights = PricingCalculator.calculateNights(checkIn, checkOut);
313	        reservation.setNights(nights);
314	
315	        BigDecimal subtotal = PricingCalculator.calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
316	        reservation.setSubtotal(subtotal);
317	
318	        BigDecimal discount = PricingCalculator.calculateDiscount(subtotal, ratePlan);
319	        reservation.setDiscount(discount);
320	
321	        BigDecimal total = PricingCalculator.calculateTotal(subtotal, discount);
322	        reservation.setTotal(total);
323	
324	        return reservationDAO.save(reservation);
325	    }
326	
327	    public Reservation confirmReservation(long reservationId, BigDecimal amountPaid) {
328	        Reservation reservation = reservationDAO.findById(reservationId)
329	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
330	
331	        if (reservation.getStatus() != ReservationStatus.PENDING) {
332	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
333	        }
334	
335	        reservation.setStatus(ReservationStatus.CONFIRMED);
336	        reservation.setAmountPaid(amountPaid);
337	        reservationDAO.save(reservation);
338	
339	        notificationService.notifyReservationConfirmed(reservation);
340	        sendGuestConfirmation(reservation);
341	
342	        logger.info("Reservation {} confirmed", reservationId);
343	        return reservation;
344	    }
345	
346	    public Reservation checkIn(long reservationId) {
347	        Reservation reservation = reservationDAO.findById(reservationId)
348	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
349	
350	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
351	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
352	        }
353	
354	        reservation.setStatus(ReservationStatus.CHECKED_IN);
355	        reservationDAO.save(reservation);
356	
357	        logger.info("Reservation {} checked in", reservationId);
358	        return reservation;
359	    }
360	
361	    public Reservation checkOut(long reservationId) {
362	        Reservation reservation = reservationDAO.findById(reservationId)
363	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
364	
365	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
366	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
367	        }
368	
369	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
370	        reservationDAO.save(reservation);
371	
372	        logger.info("Reservation {} checked out", reservationId);
373	        return reservation;
374	    }
375	
376	    public Reservation cancelReservation(long reservationId) {
377	        Reservation reservation = reservationDAO.findById(reservationId)
378	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
379	
380	        if (reservation.getStatus() == ReservationStatus.CHECKED_OUT ||
381	            reservation.getStatus() == ReservationStatus.CANCELLED) {
382	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
383	        }
384	
385	        boolean wasConfirmed = reservation.getStatus() != ReservationStatus.PENDING;
386	
387	        reservation.setStatus(ReservationStatus.CANCELLED);
388	
389	        if (wasConfirmed) {
390	            if (reservation.getRatePlan() == RatePlan.STANDARD) {
391	                reservation.setRefund(reservation.getAmountPaid());
392	            } else {
393	                reservation.setRefund(BigDecimal.ZERO);
394	            }
395	        }
396	
397	        reservationDAO.save(reservation);
398	
399	        if (wasConfirmed) {
400	            notificationService.notifyReservationCancelled(reservation);
401	        }
402	
403	        logger.info("Reservation {} cancelled", reservationId);
404	        return reservation;
405	    }
406	
407	    public Reservation getReservation(long reservationId) {
408	        return reservationDAO.findById(reservationId)
409	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
410	    }
411	
412	    private boolean isRoomUnavailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
413	        return !reservationDAO.findByRoomAndDateRange(roomNumber, checkIn, checkOut).isEmpty();
414	    }
415	
416	    private void validateInput(int roomNumber, LocalDate checkIn, LocalDate checkOut, int guests) {
417	        if (guests < 1) {
418	            throw new IllegalArgumentException("INVALID_REQUEST");
419	        }
420	
421	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
422	            throw new IllegalArgumentException("INVALID_REQUEST");
423	        }
424	    }
425	
426	    private void sendGuestConfirmation(Reservation reservation) {
427	        String document = generateConfirmation(reservation);
428	        String emailBody = String.format("Olá, %s!\n\n" +
429	                        "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
430	                        "%s\n\n" +
431	                        "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
432	                        "Até breve!",
433	                reservation.getGuestName(),
434	                document);
435	
436	        Notification notification = new Notification(
437	            MessageChannel.EMAIL,
438	            reservation.getGuestEmail(),
439	            "Reserva confirmada - Pousada Maré Alta",
440	            emailBody
