452	            Formatters.formatDate(reservation.getCheckIn()),
453	            Formatters.formatDate(reservation.getCheckOut()),
454	            reservation.getNights(),
455	            reservation.getNights() == 1 ? "diária" : "diárias"));
456	        sb.append(String.format("Diárias: %s\n", Formatters.formatMoney(reservation.getSubtotal())));
457	
458	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
459	            sb.append(String.format("Desconto: %s\n", Formatters.formatMoney(reservation.getDiscount())));
460	        }
461	
462	        sb.append(String.format("Total: %s", Formatters.formatMoney(reservation.getTotal())));
