  6	import java.sql.Connection;
  7	import java.sql.DriverManager;
  8	import java.sql.SQLException;
  9	import java.sql.Statement;
 10	
 11	public class Database {
 12	    private static final Logger logger = LoggerFactory.getLogger(Database.class);
 13	    private static Database instance;
 14	    private final String url;
 15	    private final String user;
 16	    private final String password;
 17	
 18	    private Database(String url, String user, String password) {
 19	        this.url = url;
 20	        this.user = user;
 21	        this.password = password;
 22	    }
 23	
 24	    public static synchronized Database getInstance() {
 25	        if (instance == null) {
 26	            String url = System.getenv("DB_URL");
 27	            String user = System.getenv("DB_USER");
 28	            String password = System.getenv("DB_PASSWORD");
 29	
 30	            if (url == null || user == null || password == null) {
 31	                throw new IllegalStateException("Database environment variables not set");
 32	            }
 33	
 34	            instance = new Database(url, user, password);
 35	            instance.initialize();
 36	        }
 37	        return instance;
 38	    }
 39	
 40	    public Connection getConnection() throws SQLException {
 41	        return DriverManager.getConnection(url, user, password);
 42	    }
 43	
 44	    private void initialize() {
 45	        try (Connection conn = getConnection();
 46	             Statement stmt = conn.createStatement()) {
 47	
 48	            stmt.execute("CREATE TABLE IF NOT EXISTS rooms (" +
 49	                    "number INT PRIMARY KEY," +
 50	                    "type VARCHAR(50) NOT NULL," +
 51	                    "capacity INT NOT NULL," +
 52	                    "nightly_rate NUMERIC(10, 2) NOT NULL" +
 53	                    ")");
 54	
 55	            stmt.execute("CREATE TABLE IF NOT EXISTS reservations (" +
 56	                    "id SERIAL PRIMARY KEY," +
 57	                    "room_number INT NOT NULL REFERENCES rooms(number)," +
 58	                    "guest_name VARCHAR(255) NOT NULL," +
 59	                    "guest_email VARCHAR(255) NOT NULL," +
 60	                    "guest_cpf VARCHAR(14) NOT NULL," +
 61	                    "check_in DATE NOT NULL," +
 62	                    "check_out DATE NOT NULL," +
 63	                    "guests INT NOT NULL," +
 64	                    "rate_plan VARCHAR(50) NOT NULL," +
 65	                    "nights INT NOT NULL," +
 66	                    "subtotal NUMERIC(10, 2) NOT NULL," +
 67	                    "discount NUMERIC(10, 2) NOT NULL," +
 68	                    "total NUMERIC(10, 2) NOT NULL," +
 69	                    "status VARCHAR(50) NOT NULL," +
 70	                    "amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0," +
 71	                    "refund NUMERIC(10, 2)" +
 72	                    ")");
 73	
 74	            stmt.execute("CREATE TABLE IF NOT EXISTS messages (" +
 75	                    "id SERIAL PRIMARY KEY," +
 76	                    "channel VARCHAR(50) NOT NULL," +
 77	                    "to_address VARCHAR(255) NOT NULL," +
 78	                    "subject VARCHAR(255) NOT NULL," +
 79	                    "body TEXT NOT NULL" +
 80	                    ")");
 81	
 82	            stmt.execute("CREATE INDEX IF NOT EXISTS idx_reservations_room ON reservations(room_number)");
 83	            stmt.execute("CREATE INDEX IF NOT EXISTS idx_reservations_check_in ON reservations(check_in)");
 84	            stmt.execute("CREATE INDEX IF NOT EXISTS idx_reservations_status ON reservations(status)");
 85	
 86	            initializeRooms(stmt);
 87	
 88	            logger.info("Database initialized successfully");
 89	        } catch (SQLException e) {
 90	            logger.error("Error initializing database", e);
 91	            throw new RuntimeException(e);
 92	        }
 93	    }
 94	
 95	    private void initializeRooms(Statement stmt) throws SQLException {
 96	        stmt.execute("DELETE FROM rooms");
 97	
 98	        stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (101, 'STANDARD', 2, 249.90)");
