461	
462	public class PricingCalculator {
463	
464	    public static boolean isHighSeason(LocalDate date) {
465	        Month month = date.getMonth();
466	        int dayOfMonth = date.getDayOfMonth();
467	
468	        if (month == Month.DECEMBER && dayOfMonth >= 15) return true;
469	        if (month == Month.JANUARY) return true;
470	        if (month == Month.FEBRUARY) return true;
471	        if (month == Month.JULY) return true;
472	
473	        return false;
474	    }
475	
476	    public static BigDecimal calculateNightPrice(BigDecimal nightlyRate, LocalDate night) {
477	        BigDecimal price = nightlyRate;
478	
479	        if (isHighSeason(night)) {
480	            price = price.multiply(new BigDecimal("1.20"));
481	        }
482	
483	        return MoneyRounder.round(price);
484	    }
485	
486	    public static BigDecimal calculateSubtotal(BigDecimal nightlyRate, LocalDate checkIn, LocalDate checkOut) {
487	        BigDecimal subtotal = BigDecimal.ZERO;
488	        LocalDate current = checkIn;
489	
490	        while (current.isBefore(checkOut)) {
491	            subtotal = subtotal.add(calculateNightPrice(nightlyRate, current));
492	            current = current.plusDays(1);
493	        }
494	
495	        return MoneyRounder.round(subtotal);
496	    }
497	
498	    public static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
499	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
500	            BigDecimal discount = subtotal.multiply(new BigDecimal("0.15"));
501	            return MoneyRounder.round(discount);
502	        }
503	        return BigDecimal.ZERO;
504	    }
505	
506	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
507	        BigDecimal total = subtotal.subtract(discount);
508	        return MoneyRounder.round(total);
509	    }
510	
511	    public static int calculateNights(LocalDate checkIn, LocalDate checkOut) {
512	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
513	    }
514	}

